    mediaUrl: 'https://utytejuejflw8n4e.public.blob.vercel-storage.com/eduweb/ressources/Physique-Chimie-6e-Le-on-12---Volume-d-un-liquide-et-d-un-solide-NVADUCvXa4CiqAukg82QWqeGqTRODB.mp4',
    quiz: [
      { type: 'qcu', question: 'Qu’est-ce que le volume d’un corps ?', options: ['l’espace qu’il occupe', 'la masse qu’il possède', 'la température qu’il atteint', 'la longueur qu’il mesure'], bonne: 0, commentaire: 'Le VOLUME, c’est l’ESPACE OCCUPÉ par un corps, liquide ou solide.' },
      { type: 'qcu', question: 'Qu’est-ce que la capacité d’un récipient ?', options: ['le volume maximal qu’il peut contenir', 'le volume de matière de ses parois', 'la masse du récipient quand il est vide', 'la hauteur du récipient en centimètres'], bonne: 0, commentaire: 'La CAPACITÉ d’un récipient, c’est ce qu’il PEUT CONTENIR AU PLUS.' },
      { type: 'qcu', question: 'Quelle est l’unité internationale (SI) de volume ?', options: ['le mètre cube (m³)', 'le mètre carré (m²)', 'le litre (L)', 'le kilogramme (kg)'], bonne: 0, commentaire: 'L’unité internationale de volume est le MÈTRE CUBE (m³). Le litre est une unité usuelle.' },
      { type: 'qcu', question: 'Une bouteille contient 1,5 L d’eau. Quel est ce volume en dm³ ?', options: ['1,5 dm³', '15 dm³', '150 dm³', '1 500 dm³'], bonne: 0, commentaire: '1 L = 1 dm³ : 1,5 L = 1,5 dm³.' },
      { type: 'qcu', question: 'Combien de millilitres y a-t-il dans 2 L ?', options: ['2 000 mL', '200 mL', '20 mL', '20 000 mL'], bonne: 0, commentaire: '1 L = 1 000 mL : 2 L = 2 000 mL.' },
      { type: 'qcu', question: 'Une citerne contient 3 m³ d’eau. Combien de litres cela fait-il ?', options: ['3 000 L', '300 L', '30 L', '30 000 L'], bonne: 0, commentaire: '1 m³ = 1 000 L : 3 m³ = 3 000 L.' },
      { type: 'qcu', question: 'Un flacon contient 250 mL. Quel est ce volume en cm³ ?', options: ['250 cm³', '25 cm³', '2,5 cm³', '2 500 cm³'], bonne: 0, commentaire: '1 mL = 1 cm³ : 250 mL = 250 cm³.' },
      { type: 'vraifaux', question: 'Pour lire le volume, on peut tenir l’éprouvette penchée à la main.', bonne: false, commentaire: 'Faux : l’éprouvette doit être BIEN DROITE, posée sur un support HORIZONTAL.' },
      { type: 'qcu', question: 'Avant de lire le volume sur une éprouvette, que faut-il repérer ?', options: ['l’unité et la valeur d’une graduation', 'la couleur et l’odeur du liquide', 'la marque et le prix de l’éprouvette', 'la température de la salle de classe'], bonne: 0, commentaire: 'Je repère l’UNITÉ et la VALEUR D’UNE GRADUATION avant de lire.' },
      { type: 'qcu', question: 'Observe ces trois positions de l’œil devant une éprouvette d’eau. Laquelle permet de lire correctement le volume ?', image: '/images/quiz/circuit/oeil-menisque.svg', imageAlt: 'Une éprouvette contenant de l’eau et trois yeux à gauche, reliés au bas du ménisque par des pointillés. L’œil A est plus haut que le liquide, l’œil B est exactement à la hauteur du bas du ménisque, l’œil C est plus bas', options: ['la position B', 'la position A', 'la position C', 'les trois positions'], bonne: 0, commentaire: 'Pour l’eau, l’œil se place À LA HAUTEUR du BAS DU MÉNISQUE : c’est la position B. Ainsi, l’erreur diminue.' },
      { type: 'qcu', question: 'Observe cette éprouvette graduée en millilitres. Quel volume d’eau contient-elle ?', image: '/images/quiz/circuit/eprouvette-lecture.svg', imageAlt: 'Partie agrandie d’une éprouvette graduée en millilitres, avec les nombres 30, 40, 50 et 60 et quatre petits traits entre deux nombres. L’eau forme un ménisque : son bas est au troisième petit trait au-dessus de 40, ses bords remontent jusqu’au quatrième', options: ['46 mL', '48 mL', '43 mL', '47 mL'], bonne: 0, commentaire: 'Entre 40 et 50, il y a 5 intervalles : une graduation vaut 2 mL. Le bas du ménisque est au 3e trait au-dessus de 40 : 40 + 3 × 2 = 46 mL.' },
      { type: 'vraifaux', question: 'Quand on lit un volume, on note seulement le nombre, sans l’unité.', bonne: false, commentaire: 'Faux : on note la VALEUR et l’UNITÉ, par exemple 25 mL.' },
      { type: 'classement', question: 'Remets dans l’ordre les étapes pour mesurer le volume d’un solide par déplacement d’eau :', items: ['Je verse de l’eau et je lis son volume V₁', 'Je plonge le solide dans l’eau', 'Je lis le nouveau volume V₂', 'Je calcule le volume du solide'], ordre: [0, 1, 2, 3], commentaire: 'On lit d’abord le volume initial V₁, on plonge le solide, on lit le volume final V₂, puis on calcule.' },
      { type: 'qcm', question: 'Pendant une mesure par déplacement d’eau, que faut-il éviter ?', options: ['des bulles d’air collées au solide', 'de renverser de l’eau', 'un solide qui se dissout dans l’eau', 'd’utiliser une éprouvette graduée'], bonnes: [0, 1, 2], commentaire: 'Il faut éviter les BULLES, un solide qui se DISSOUT et l’EAU RENVERSÉE : sinon le résultat est faux.' },
      { type: 'vraifaux', question: 'Pour mesurer son volume par déplacement d’eau, le solide doit être totalement immergé.', bonne: true, commentaire: 'Vrai : le solide doit être TOTALEMENT IMMERGÉ, sinon une partie de son volume n’est pas comptée.' },
      { type: 'qcu', question: 'On note V₁ le volume d’eau avant et V₂ le volume après avoir immergé le solide. Comment calcule-t-on le volume du solide ?', options: ['V₂ − V₁', 'V₁ − V₂', 'V₁ + V₂', 'V₁ × V₂'], bonne: 0, commentaire: 'Volume du solide = volume final moins volume initial : V₂ − V₁.' },
      { type: 'qcu', question: 'Le niveau d’eau passe de 50 mL à 68 mL quand on immerge un solide. Quel est le volume du solide ?', options: ['18 mL', '68 mL', '118 mL', '50 mL'], bonne: 0, commentaire: '68 mL − 50 mL = 18 mL : c’est le volume du solide.' },
      { type: 'qcu', question: 'Observe les deux éprouvettes, avant et après avoir plongé le caillou. Quel est le volume du caillou ?', image: '/images/quiz/circuit/deplacement-eau.svg', imageAlt: 'Deux éprouvettes graduées en millilitres, de 0 à 60, avec un petit trait au milieu entre deux nombres. AVANT : l’eau arrive à 30. APRÈS, avec un caillou au fond : l’eau arrive au petit trait entre 40 et 50', options: ['15 mL', '45 mL', '75 mL', '3 mL'], bonne: 0, commentaire: 'Ici, une graduation vaut 5 mL : l’eau passe de 30 mL à 45 mL. 45 − 30 = 15 mL.' },
      { type: 'qcu', question: 'Comment calcule-t-on le volume d’un pavé ?', options: ['longueur × largeur × hauteur', 'longueur + largeur + hauteur', 'longueur × largeur', '2 × (longueur + largeur)'], bonne: 0, commentaire: 'Pavé : V = L × l × h (longueur fois largeur fois hauteur).' },
      { type: 'qcu', question: 'Observe ce pavé de 5 cm de long, 4 cm de large et 2 cm de haut. Quel est son volume ?', image: '/images/quiz/circuit/pave-dimensions.svg', imageAlt: 'Un pavé droit. Sa longueur mesure 5 cm, sa largeur 4 cm et sa hauteur 2 cm', options: ['40 cm³', '11 cm³', '20 cm³', '20 cm²'], bonne: 0, commentaire: '5 × 4 × 2 = 40 : le volume est 40 cm³. 5 × 4 = 20 cm² n’est que l’aire de la base : il faut encore multiplier par la hauteur.' },
      { type: 'vraifaux', question: 'Pour calculer le volume d’un pavé, toutes ses longueurs doivent être exprimées dans la même unité.', bonne: true, commentaire: 'Vrai : toutes les longueurs doivent avoir LA MÊME UNITÉ, sinon le calcul est faux.' },
      { type: 'courte', question: 'Un cube a une arête de 3 cm. Quel est son volume, en cm³ ?', motsCles: [['27', 'vingt sept']], reponseAffichee: '27 cm³ (3 × 3 × 3)', commentaire: 'Cube : V = côté × côté × côté = 3 × 3 × 3 = 27 cm³.' },
    ],
